package mcp

import (
	"encoding/json"
	"os"
	"reflect"
	"sort"
	"strings"
	"testing"
	"unicode"
)

// redactVectors is generated by running the real Python implementation
// (aikito/mcp/redact.py) — see testdata/redact_vectors.json. Every expected
// value below comes from live Python output, not hand-derived expectations.
// Regenerate with testdata/gen_redact_vectors.py (see redactVectorsSource).
type redactVectors struct {
	SensitiveParam     [][2]any `json:"sensitive_param"`
	CredentialHeader   [][2]any `json:"credential_header"`
	Loopback           [][2]any `json:"loopback"`
	HasSensitiveParams [][2]any `json:"has_sensitive_params"`
	ProbeError         []struct {
		Text    string            `json:"text"`
		Headers map[string]string `json:"headers"`
		Want    string            `json:"want"`
	} `json:"probe_error"`
	Partition           [][5]string `json:"partition"`
	URLsInText          [][2]any    `json:"urls_in_text"`
	IsAuthorizationURL  [][2]any    `json:"is_authorization_url"`
	RedactSensitiveURLs [][2]string `json:"redact_sensitive_urls"`
	PrintableRanges     [][2]int    `json:"printable_ranges"`
	PythonUnicode       string      `json:"python_unicode_version"`
}

// redactVectorsSource is produced by testdata/gen_redact_vectors.py, which
// imports aikito.mcp.redact from the reference checkout (AIKITO_PYTHON_SRC,
// else a sibling ../aikito/src) and records each function's actual return
// value for a fixed set of inputs, plus run-length ranges of every code
// point for which str.isprintable() is True. Regenerate with:
//
//	python3 internal/mcp/testdata/gen_redact_vectors.py
const redactVectorsSource = "testdata/redact_vectors.json"

func loadRedactVectors(t *testing.T) redactVectors {
	t.Helper()
	data, err := os.ReadFile(redactVectorsSource)
	if err != nil {
		t.Fatal(err)
	}
	var v redactVectors
	if err := json.Unmarshal(data, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func boolCases(t *testing.T, name string, cases [][2]any, fn func(string) bool) {
	t.Helper()
	if len(cases) == 0 {
		t.Fatalf("%s: no vectors loaded", name)
	}
	for _, c := range cases {
		in, want := c[0].(string), c[1].(bool)
		if got := fn(in); got != want {
			t.Errorf("%s(%q) = %v, Python says %v", name, in, got, want)
		}
	}
}

func TestIsSensitiveURLParameterMatchesPython(t *testing.T) {
	v := loadRedactVectors(t)
	boolCases(t, "IsSensitiveURLParameter", v.SensitiveParam, IsSensitiveURLParameter)

	// Guard against the vector set silently losing its negative cases:
	// over-redaction breaks legitimate output just as surely as
	// under-redaction leaks secrets.
	negatives := 0
	for _, c := range v.SensitiveParam {
		if !c[1].(bool) {
			negatives++
		}
	}
	if negatives < 20 {
		t.Errorf("expected at least 20 non-sensitive parameter vectors, got %d", negatives)
	}
}

